fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    
    // Copy all elements from v1
    for &item in v1 {
        result.push(item);
    }
    
    // Copy all elements from v2
    for &item in v2 {
        result.push(item);
    }
    
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // First, take all elements of A except the last one
    let mut result = Vec::with_capacity(first.len() - 1 + second.len());
    
    // Copy all elements from first except the last one
    for i in 0..first.len() - 1 {
        result.push(first[i]);
    }
    
    // Append all elements from second
    for &item in second {
        result.push(item);
    }
    
    result
}